# ===== UNIT 3: PHARMACOEPIDEMIOLOGY (15 new) =====
q.append({"unit_id": "phs-unit-3", "question_text": "The epidemiological triad of disease consists of:", "options": ["Agent, host and environment", "Doctor, patient and hospital", "Bacteria, virus and fungus", "Heredity, diet and climate"], "correct_index": 0, "explanation": "Disease results from the interaction of an agent (cause), a susceptible host and the environment that brings them together — the epidemiological triad.", "difficulty": "easy", "tags": ["epidemiology", "triad"]})
q.append({"unit_id": "phs-unit-3", "question_text": "In epidemiology, the 'reservoir' of an infection is:", "options": ["The place where the infectious agent normally lives, grows and multiplies", "The medicine used to treat the infection", "The laboratory where the organism is cultured", "The hospital ward where patients are kept"], "correct_index": 0, "explanation": "The reservoir is any human, animal or environmental site where the agent survives and from which it can be transmitted, e.g., humans for measles.", "difficulty": "medium", "tags": ["epidemiology", "chain of infection"]})
q.append({"unit_id": "phs-unit-3", "question_text": "In the chain of infection, the portal of exit is:", "options": ["The route by which the agent leaves the reservoir, such as the respiratory tract in coughing", "The skin barrier of the susceptible host", "The microscope slide used in the laboratory", "The syringe used for immunisation"], "correct_index": 0, "explanation": "After multiplying in the reservoir, the agent must leave through a portal of exit (respiratory, intestinal, skin) to reach a new host.", "difficulty": "medium", "tags": ["epidemiology", "chain of infection"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Direct transmission of infection occurs when the agent is transferred:", "options": ["Immediately from an infected person or animal to a susceptible host", "Through contaminated water or food", "By an insect vector such as a mosquito", "Through air over long distances"], "correct_index": 0, "explanation": "Direct transmission includes person-to-person contact, droplet spread over short distances and contact with soil, without any intermediate vehicle.", "difficulty": "easy", "tags": ["epidemiology", "transmission"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Transmission of infection through contaminated water, food or a fomite is called:", "options": ["Vehicle-borne (indirect) transmission", "Vertical transmission", "Direct contact transmission", "Genetic transmission"], "correct_index": 0, "explanation": "Indirect transmission through vehicles occurs when the agent passes via water, food, blood or inanimate objects (fomites) to the host.", "difficulty": "easy", "tags": ["epidemiology", "transmission"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Transmission of an infection from a mother to her baby during pregnancy or birth is described as:", "options": ["Vertical transmission", "Vehicle-borne transmission", "Airborne transmission", "Vector-borne transmission"], "correct_index": 0, "explanation": "Vertical transmission passes infection across the placenta, during delivery or through breast milk, as with HIV, syphilis or hepatitis B.", "difficulty": "medium", "tags": ["epidemiology", "transmission"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Infections such as measles and tuberculosis spread mainly by:", "options": ["Airborne droplet nuclei inhaled by the susceptible host", "Contaminated drinking water supplies", "The bite of female mosquitoes", "Blood transfusion only"], "correct_index": 0, "explanation": "Droplet nuclei expelled during coughing or sneezing remain suspended in air and are inhaled, spreading measles, TB and influenza.", "difficulty": "easy", "tags": ["epidemiology", "transmission"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Virulence of an infectious agent refers to its:", "options": ["Ability to produce severe disease", "Ability to enter the host", "Speed of spread in the community", "Resistance to antibiotics"], "correct_index": 0, "explanation": "Virulence is the capacity of an agent to cause severe illness (e.g., case fatality), while infectivity is its power to establish infection.", "difficulty": "medium", "tags": ["epidemiology", "agent"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Which of the following is a host factor that influences the occurrence of infectious disease?", "options": ["The nutritional and immune status of the person", "The colour of the hospital building", "The price of the vaccine", "The number of doctors in a town"], "correct_index": 0, "explanation": "Age, sex, nutrition, immunity and genetic make-up of the host determine susceptibility to an infectious agent.", "difficulty": "easy", "tags": ["epidemiology", "host"]})
q.append({"unit_id": "phs-unit-3", "question_text": "Attack rate in an epidemic is calculated as:", "options": ["Number of persons who become ill divided by the population exposed, during an outbreak", "Total deaths in the country in one year", "Number of cases in the previous decade", "Ratio of males to females in a village"], "correct_index": 0, "explanation": "Attack rate is a special incidence rate used during outbreaks: cases among the exposed group divided by the total exposed, often over the epidemic period.", "difficulty": "medium", "tags": ["epidemiology", "attack rate"]})
q.append({"unit_id": "phs-unit-3", "question_text": "The secondary attack rate measures:", "options": ["Spread of disease among susceptible contacts of primary cases within a household", "Deaths among hospitalised patients only", "Disease in people with no contact at all", "The annual birth rate of the community"], "correct_index": 0, "explanation": "Secondary attack rate = new cases among contacts of primary cases divided by the number of susceptible contacts, indicating person-to-person spread.", "difficulty": "hard", "tags": ["epidemiology", "attack rate"]})
q.append({"unit_id": "phs-unit-3", "question_text": "A cross-sectional (prevalence) study measures disease and exposure:", "options": ["At the same point in time in a defined population", "By following people forward for many years", "Only after the disease has caused death", "In laboratory animals under controlled conditions"], "correct_index": 0, "explanation": "Cross-sectional surveys examine exposure and disease simultaneously in a population at one time, giving prevalence rather than incidence.", "difficulty": "medium", "tags": ["epidemiology", "study types"]})
q.append({"unit_id": "phs-unit-3", "question_text": "The neonatal mortality rate refers to deaths occurring within the first:", "options": ["28 days of life per 1000 live births", "Year of life per 1000 live births", "Five years of life", "Week of pregnancy"], "correct_index": 0, "explanation": "Neonatal mortality counts deaths in the first 28 completed days of life per 1000 live births, a sensitive indicator of newborn care.", "difficulty": "medium", "tags": ["epidemiology", "mortality"]})
q.append({"unit_id": "phs-unit-3", "question_text": "The maternal mortality ratio (MMR) is expressed as the number of maternal deaths per:", "options": ["100,000 live births", "1,000 live births", "10,000 total population", "100 pregnancies"], "correct_index": 0, "explanation": "MMR is maternal deaths from pregnancy-related causes per 100,000 live births, reflecting the quality of obstetric care.", "difficulty": "medium", "tags": ["epidemiology", "mortality"]})
q.append({"unit_id": "phs-unit-3", "question_text": "The specificity of a screening test is its ability to:", "options": ["Correctly identify people who do not have the disease", "Detect all those who truly have the disease", "Predict future deaths in the population", "Measure the severity of the disease"], "correct_index": 0, "explanation": "Specificity is the proportion of truly non-diseased persons correctly excluded by the test, while sensitivity detects those who are truly diseased.", "difficulty": "hard", "tags": ["epidemiology", "screening"]})

# ===== UNIT 4: ENVIRONMENTAL HEALTH (15 new) =====
