q.append({"unit_id": "phs-unit-4", "question_text": "Excess fluoride in drinking water over many years mainly causes:", "options": ["Dental and skeletal fluorosis", "Anaemia and fatigue", "Goitre and thyroid swelling", "Kidney stones only"], "correct_index": 0, "explanation": "High fluoride levels (>1.5 mg/L) cause mottling of teeth (dental fluorosis) and, with higher exposure, crippling skeletal fluorosis.", "difficulty": "medium", "tags": ["environmental health", "water quality"]})
