q.append({"unit_id": "phs-unit-4", "question_text": "Carbon monoxide in vehicle exhaust is dangerous because it:", "options": ["Combines with haemoglobin and prevents oxygen transport in the blood", "Damages only the skin surface", "Makes the air smell of rotten eggs", "Cools the body below normal temperature"], "correct_index": 0, "explanation": "Carbon monoxide binds haemoglobin about 250 times more avidly than oxygen, forming carboxyhaemoglobin and causing tissue hypoxia.", "difficulty": "medium", "tags": ["environmental health", "air pollution"]})
